```js
// --- Brick collision (swept AABB) ------------------------------------------

// Sweeps the ball's box from its previous position to its current one and
// returns the first brick hit along the way (slab method). `null` when the
// motion never overlaps the brick. `dt`-independent: the sweep covers the
// whole displacement, so a fast ball cannot tunnel through a brick.
function sweepBrickHit(ball, brick, prevX, prevY) {
  const dx = ball.x - prevX;
  const dy = ball.y - prevY;
  const r = ball.r;

  // Per-axis entry/exit times (normalized to the motion, t in [0, 1]).
  let tEnterX = -Infinity;
  let tExitX = Infinity;
  if (dx !== 0) {
    const a = (brick.x - prevX - r) / dx;
    const b = (brick.x + brick.w - prevX + r) / dx;
    tEnterX = Math.min(a, b);
    tExitX = Math.max(a, b);
  } else if (!(ball.x + r > brick.x && ball.x - r < brick.x + brick.w)) {
    return null; // no horizontal motion and no overlap on x
  }

  let tEnterY = -Infinity;
  let tExitY = Infinity;
  if (dy !== 0) {
    const a = (brick.y - prevY - r) / dy;
    const b = (brick.y + brick.h - prevY + r) / dy;
    tEnterY = Math.min(a, b);
    tExitY = Math.max(a, b);
  } else if (!(ball.y + r > brick.y && ball.y - r < brick.y + brick.h)) {
    return null; // no vertical motion and no overlap on y
  }

  const tEnter = Math.max(tEnterX, tEnterY);
  const tExit = Math.min(tExitX, tExitY);
  if (tEnter > tExit || tExit < 0 || tEnter > 1) return null;

  // The axis whose slab was entered LAST is the face that was hit first.
  // Equal entry times mean the ball is on a corner: both axes are touched.
  const EPS = 1e-9;
  let axis;
  if (tEnterX > tEnterY + EPS) axis = 'x';
  else if (tEnterY > tEnterX + EPS) axis = 'y';
  else axis = 'corner';
  return { brick, axis };
}

// Resolves the ball against the bricks for this time step: destroys the
// first brick hit and bounces off its face. ONE bounce per pass — the ball
// is pushed out of the brick, so later bricks in the same pass no longer
// overlap it (a seam would otherwise flip the same axis twice and cancel).
export function collideBricks(state, prevX, prevY) { ... }
