function sweepBricks(state, prevX, prevY) {
  const { ball, bricks } = state;
  let best = null;
  let bestT = Infinity;
  for (const brick of bricks) {
    if (!brick.alive) continue;
    const hit = sweepBrickHit(ball, brick, prevX, prevY);
    if (!hit) continue;
    // earliest contact wins (tie: first brick in grid order)
    if (hit.t < bestT) { best = hit; bestT = hit.t; }
  }
  if (!best) return null;
  resolveBounce(ball, best.brick, best.axis);
  return best;
}
