```js
function resolveBounce(ball, brick, axis) {
  if (axis === 'x') {
    if (ball.vx > 0) ball.x = brick.x - ball.r;        // hit the left face
    else ball.x = brick.x + brick.w + ball.r;          // hit the right face
    ball.vx = -ball.vx;
  } else if (axis === 'y') {
    if (ball.vy > 0) ball.y = brick.y - ball.r;        // hit the top face
    else ball.y = brick.y + brick.h + ball.r;          // hit the bottom face
    ball.vy = -ball.vy;
  } else {
    // Corner: both faces are touched at the same time, both axes flip.
    if (ball.vx > 0) ball.x = brick.x - ball.r;
    else ball.x = brick.x + brick.w + ball.r;
    if (ball.vy > 0) ball.y = brick.y - ball.r;
    else ball.y = brick.y + brick.h + ball.r;
    ball.vx = -ball.vx;
    ball.vy = -ball.vy;
  }
}
```

