// --- Brick collision (resolution primitive) --------------------------------

// Sweeps the ball's box from its previous position to its current one and
// resolves the first brick hit along the way (slab method). Returns the
// destroyed brick, or null.
//
// The slab method gives, per axis, the entry and exit times of the motion
// within the brick's range. The axis whose slab was entered LAST is the face
// that was hit first; equal entry times mean the ball is on a corner and
// both axes bounce. The sweep covers the whole displacement, so a fast ball
// can never tunnel through a brick, whatever the time step.
function hitBrick(state, prevX, prevY) {
  const { ball, bricks } = state;

  for (const brick of bricks) {
    if (!brick.alive) continue;
    if (!sweepBrick(ball, brick, prevX, prevY)) continue;
    return brick;
  }
  return null;
}

// Slab test: does the ball's box, swept from (prevX, prevY) to its current
// position, touch the brick? If so, bounce off the face and push the ball
// back out of the rectangle. At most ONE bounce per pass: the loop in
// `hitBrick` stops at the first brick, so a seam (gap 8 px < ball diameter
// 14 px, two bricks overlapped at once) can never flip the same axis twice.
function sweepBrick(ball, brick, prevX, prevY) {
  const r = ball.r;
  const dx = ball.x - prevX;
  const dy = ball.y - prevY;

  // Entry/exit times on each axis, normalized to the motion (t in [0, 1]).
  // No motion on an axis: the overlap must already hold for the whole pass.
  let tEnterX = -Infinity;
  let tExitX = Infinity;
  if (dx !== 0) {
    const a = (brick.x - prevX - r) / dx;
    const b = (brick.x + brick.w - prevX + r) / dx;
    tEnterX = Math.min(a, b);
    tExitX = Math.max(a, b);
  } else if (!(ball.x + r > brick.x && ball.x - r < brick.x + brick.w)) {
    return false;
  }

  let tEnterY = -Infinity;
  let tExitY = Infinity;
  if (dy !== 0) {
    const a = (brick.y - prevY - r) / dy;
    const b = (brick.y + brick.h - prevY + r) / dy;
    tEnterY = Math.min(a, b);
    tExitY = Math.max(a, b);
  } else if (!(ball.y + r > brick.y && ball.y - r < brick.y + brick.h)) {
    return false;
  }

  const tEnter = Math.max(tEnterX, tEnterY);
  const tExit = Math.min(tExitX, tExitY);
  if (tEnter > tExit || tExit < 0 || tEnter > 1) return false;

  // The face: the axis entered last; on a tie the ball is on a corner and
  // both components bounce. Then push the ball out of the rectangle on the
  // bounced axis(es): after resolution the ball no longer overlaps.
  const EPS = 1e-9;
  if (tEnterX > tEnterY + EPS) {
    if (ball.vx > 0) ball.x = brick.x - r;
    else ball.x = brick.x + brick.w + r;
    ball.vx = -ball.vx;
  } else if (tEnterY > tEnterX + EPS) {
    if (ball.vy > 0) ball.y = brick.y - r;
    else ball.y = brick.y + brick.h + r;
    ball.vy = -ball.vy;
  } else {
    // Corner: both faces touched at the same time.
    if (ball.vx > 0) ball.x = brick.x - r;
    else ball.x = brick.x + brick.w + r;
    if (ball.vy > 0) ball.y = brick.y - r;
    else ball.y = brick.y + brick.h + r;
    ball.vx = -ball.vx;
    ball.vy = -ball.vy;
  }
  return true;
}

// --- Physics (movement + wall/paddle/brick bounces) ------------------------

// Advances the ball by a time step `dt` (in seconds) and handles bounces off
// the walls, the paddle and the bricks. Returns `true` if the ball is lost
// (exits through the bottom).
export function step(state, dt) {
  const { ball, paddle } = state;

  const prevX = ball.x;
  const prevY = ball.y;
  ball.x += ball.vx * dt;
  ball.y += ball.vy * dt;

  // Bricks: swept collision over the displacement just made, one bounce per
  // pass. The ball is pushed out of the brick, so it can never stay stuck.
  const brick = hitBrick(state, prevX, prevY);
  if (brick) {
    brick.alive = false;
    state.combo += 1;
    state.score += scoreForBrick(brick, state.combo);
  }

