// --- Collision (tested primitive) ------------------------------------------

// True if the ball (circle approximated by its box) overlaps the brick.
// Simple AABB test: it only says WHETHER the ball and the brick overlap, not
// WHICH face was hit. The missing bounce in frame() is what lets the ball plow
// straight through bricks (see #1).
export function collides(ball, brick) {
  return (
    ball.x + ball.r > brick.x &&
    ball.x - ball.r < brick.x + brick.w &&
    ball.y + ball.r > brick.y &&
    ball.y - ball.r < brick.y + brick.h
  );
}

// --- Score & combo (NOT covered by tests — debt #5) ------------------------

// Combo multiplier. UNBOUNDED today: a long combo makes the score blow up
// uncontrollably (see #5, expected improvement = clamp it).
export function comboMultiplier(combo) {
  return 1 + combo * 0.5;
}

// Points earned for breaking a brick, combo included.
export function scoreForBrick(brick, combo) {
  return Math.round(brick.points * comboMultiplier(combo));
}

// --- Best score persistence ------------------------------------------------

// Reads the best score from a localStorage-compatible storage.
// Robust to corrupted or missing storage: returns 0 instead of throwing.
export function loadBest(storage) {
  if (!storage) return 0;
  try {
    const raw = storage.getItem(STORAGE_KEY);
    const value = Number.parseInt(raw, 10);
    return Number.isFinite(value) && value > 0 ? value : 0;
  } catch {
    return 0;
  }
}

// Writes the best score if the current score beats it. Returns the updated best.
export function saveBest(storage, score) {
  const best = loadBest(storage);
  if (score > best && storage) {
    try {
      storage.setItem(STORAGE_KEY, String(score));
    } catch {
      // storage unavailable (private mode, quota): silently ignore
    }
    return score;
  }
  return best;
}

// --- Brick collision (resolution primitive) --------------------------------

// Sweeps the ball's box from its previous position to its current one and
// resolves the first brick hit along the way (slab method). Returns the
// destroyed brick, or null.
//
// The slab method gives, per axis, the entry and exit times of the motion
// within the brick's range. The axis whose slab was entered LAST is the face
// that was hit first; equal entry times mean the ball is on a corner and
// both axes bounce. The sweep covers the whole displacement, so a fast ball
// can never tunnel through a brick, whatever the time step.
function hitBrick(state, prevX, prevY) {
  const { ball, bricks } = state;

  for (const brick of bricks) {
    if (!brick.alive) continue;
    if (!sweepBrick(ball, brick, prevX, prevY)) continue;
    return brick;
  }
  return null;
}

// Slab test: does the ball's box, swept from (prevX, prevY) to its current
// position, touch the brick? If so, bounce off the face and push the ball
// back out of the rectangle. At most ONE bounce per pass: the loop in
// `hitBrick` stops at the first brick, so a seam (gap 8 px < ball diameter
// 14 px, two bricks overlapped at once) can never flip the same axis twice.
function sweepBrick(ball, brick, prevX, prevY) {
  const r = ball.r;
  const dx = ball.x - prevX;
  const dy = ball.y - prevY;

  // Entry/exit times on each axis, normalized to the motion (t in [0, 1]).
  // No motion on an axis: the overlap must already hold for the whole pass.
  let tEnterX = -Infinity;
  let tExitX = Infinity;
  if (dx !== 0) {
    const a = (brick.x - prevX - r) / dx;
    const b = (brick.x + brick.w - prevX + r) / dx;
    tEnterX = Math.min(a, b);
    tExitX = Math.max(a, b);
  } else if (!(ball.x + r > brick.x && ball.x - r < brick.x + brick.w)) {
    return false;
  }

